mapper.select:
SELECT DISTINCT a.employee_id
FROM biz_application a
WHERE a.type = 'LEAVE'
  AND a.status = 'APPROVED'
  AND a.start_time < #{to}
  AND a.end_time >= #{from}

mapper.delete:
DELETE FROM att_daily_stat
WHERE stat_date = #{statDate}
  AND employee_id NOT IN (SELECT id FROM hr_employee WHERE status = 1)
